1	package meter
2	
3	import (
4		"sort"
5		"sync"
6		"time"
7	)
8	
9	// Service 是订阅、用量与账单的本地内存服务。
10	// 单个 *Service 可被多个 goroutine 并发使用：重复提交只会生效一次。
11	type Service struct {
12		mu       sync.Mutex
13		now      func() time.Time
14		accounts map[string]*account
15		plans    map[string]Plan
16	}
17	
18	type subRecord struct {
19		planID      string
20		terms       PlanTerms
21		activatedAt time.Time
22		// termsHistory 按生效月份升序记录每次换套餐后的条件；
23		// 首条为开通当月适用的开通快照。账单按账期从中取当时适用的条件。
24		termsHistory []termsEntry
25		// pending 尚未生效的换套餐安排，每账户至多一条；nil 表示无安排。
26		pending *PlanChange
27		// cancelEnd 已安排的终止时刻（取消请求时刻的下一个 UTC 自然月月初）。
28		// 非 nil 且尚未到达时为等待取消状态；到达后本订阅段终止并移入 history。
29		cancelEnd *time.Time
30		// endedAt 已终止订阅段的实际终止时刻；当前有效段为 nil。
31		endedAt *time.Time
32	}
33	
34	type eventRecord struct {
35		at     time.Time
36		qty    int64
37		period Month
38	}
39	
40	type billRecord struct {
41		bill Bill
42	}
43	
44	type paymentRecord struct {
45		period Month
46		amount int64
47		// balance 与 settled 是本笔付款首次成功登记完成时账单的余额与付清状态。
48		// 完全相同的重报原样返回该历史结果，不随后续付款或账单当前状态变化。
49		balance int64
50		settled bool
51	}
52	
53	type account struct {
54		id       string
55		sub      *subRecord
56		history  []*subRecord
57		events   map[string]eventRecord
58		usage    map[Month]int64
59		bills    map[Month]*billRecord
60		payments map[string]paymentRecord
61	}
62	
63	// NewService 创建一个以系统时钟判断“当前时刻”的服务。
64	func NewService() *Service {
65		return NewServiceWithClock(time.Now)
66	}
67	
68	// NewServiceWithClock 创建使用自定义时钟的服务，便于测试账期与截止时刻。
69	func NewServiceWithClock(now func() time.Time) *Service {
70		if now == nil {
71			now = time.Now
72		}
73		return &Service{
74			now:      now,
75			accounts: make(map[string]*account),
76			plans:    make(map[string]Plan),
77		}
78	}
79	
80	func (s *Service) nowUTC() time.Time {
81		return s.now().UTC()
82	}
83	
84	// CreateAccount 创建业务账户。账户标识必须非空且唯一。
85	func (s *Service) CreateAccount(id string) error {
86		if id == "" {
87			return invalidf("account id is empty")
88		}
89		s.mu.Lock()
90		defer s.mu.Unlock()
91		if _, ok := s.accounts[id]; ok {
92			return ErrAccountExists
93		}
94		s.accounts[id] = &account{
95			id:       id,
96			events:   make(map[string]eventRecord),
97			usage:    make(map[Month]int64),
98			bills:    make(map[Month]*billRecord),
99			payments: make(map[string]paymentRecord),
100		}
101		return nil
102	}
103	
104	func validatePlan(p Plan) error {
105		if p.ID == "" {
106			return invalidf("plan id is empty")
107		}
108		if p.MonthlyFee < 0 || p.IncludedUnits < 0 || p.OveragePrice < 0 {
109			return invalidf("plan %q has negative amount or quantity", p.ID)
110		}
111		if p.TaxRateBasisPoints < 0 || p.TaxRateBasisPoints > 10000 {
112			return invalidf("plan %q tax rate %d out of [0,10000]", p.ID, p.TaxRateBasisPoints)
113		}
114		return nil
115	}
116	
117	// CreatePlan 创建套餐。金额单位为分，税率为万分比且在 [0,10000]。
118	func (s *Service) CreatePlan(p Plan) error {
119		if err := validatePlan(p); err != nil {
120			return err
121		}
122		s.mu.Lock()
123		defer s.mu.Unlock()
124		if _, ok := s.plans[p.ID]; ok {
125			return ErrPlanExists
126		}
127		s.plans[p.ID] = p
128		return nil
129	}
130	
131	// UpdatePlan 更新套餐当前条件。只影响之后开通的订阅，
132	// 已开通订阅继续使用开通时保存的快照。
133	func (s *Service) UpdatePlan(p Plan) error {
134		if err := validatePlan(p); err != nil {
135			return err
136		}
137		s.mu.Lock()
138		defer s.mu.Unlock()
139		if _, ok := s.plans[p.ID]; !ok {
140			return ErrPlanNotFound
141		}
142		s.plans[p.ID] = p
143		return nil
144	}
145	
146	// Subscribe 为账户开通订阅，并保存当时的套餐条件快照。
147	// 每个账户只允许一份有效订阅；从 activatedAt 起接收用量，
148	// 首月仍收完整月费并提供完整额度。
149	//
150	// activatedAt 可以晚于当前时刻，即提前登记一份尚未生效的订阅：登记会被保留，
151	// 但在实际开通时刻到达前 Status 的 Subscribed 为 false、CurrentTerms 为零值，
152	// 也没有待换套餐安排与待取消终止时刻；此期间再次开通仍返回
153	// ErrSubscriptionExists，安排换套餐、登记取消返回 ErrSubscriptionNotActivated。
154	// 判断以实际开通时刻为界（按同一瞬间比较，带时区的开通时间结果一致），不按
155	// 开通月份提前生效；到达开通时刻后查询即显示有效订阅与登记时保存的完整套餐
156	// 条件快照，等待期间修改套餐定义不改变该快照。
157	//
158	// 订阅终止（按月取消到达终止时刻）后可用本入口重新开通：activatedAt 不得早于
159	// 上一段订阅的终止时刻；重新开通保存当时的套餐条件，当月仍收完整月费、给完整
160	// 额度。重新开通不重置账户内事件与付款标识，也不清除旧欠费。同样允许登记未来
161	// 的重新开通时刻：旧订阅已结束、新订阅尚未开始的间隔中查询不显示任何生效套餐，
162	// 历史用量与账单继续可查。
163	func (s *Service) Subscribe(accountID, planID string, activatedAt time.Time) error {
164		if accountID == "" {
165			return invalidf("account id is empty")
166		}
167		if planID == "" {
168			return invalidf("plan id is empty")
169		}
170		if activatedAt.IsZero() {
171			return invalidf("activated at is zero")
172		}
173		s.mu.Lock()
174		defer s.mu.Unlock()
175		acc, ok := s.accounts[accountID]
176		if !ok {
177			return ErrAccountNotFound
178		}
179		now := s.nowUTC()
180		// 与其他入口保持一致：先让已到期的换套餐/取消落入历史。
181		s.settleLocked(acc, now)
182		plan, ok := s.plans[planID]
183		if !ok {
184			return ErrPlanNotFound
185		}
186		if acc.sub != nil {
187			return ErrSubscriptionExists
188		}
189		activated := activatedAt.UTC()
190		// 重新开通时刻不得早于上一段订阅的终止时刻。
191		if n := len(acc.history); n > 0 {
192			if activated.Before(*acc.history[n-1].endedAt) {
193				return ErrResubscribeBeforeEnd
194			}
195		}
196		acc.sub = &subRecord{
197			planID:      planID,
198			terms:       termsOf(plan),
199			activatedAt: activated,
200			termsHistory: []termsEntry{{
201				effective: MonthOf(activated),
202				terms:     termsOf(plan),
203			}},
204		}
205		return nil
206	}
207	
208	// nextMonth 返回 period 的下一个 UTC 自然月。
209	func nextMonth(period Month) Month {
210		return MonthOf(period.End())
211	}
212	
213	// settleLocked 让当前订阅段中已到生效时刻的换套餐安排落入条件历史，
214	// 并在到达取消终止时刻时把当前段标记终止、移入 acc.history。
215	// 到达月初零点（或终止时刻）即生效，无需先上报用量或生成账单；即使中间若干月
216	// 没有调用服务，再次进入时也会在此一次性补齐。调用时持有 s.mu。
217	//
218	// 开通时刻尚未到达的订阅段只是提前登记：它尚未生效，既没有已生效的套餐条件，
219	// 也不可能有待换套餐安排或待取消终止时刻，因此在到达开通时刻前不做任何处理，
220	// 尤其不能按开通月份让条件“提前生效”。
221	func (s *Service) settleLocked(acc *account, now time.Time) {
222		sub := acc.sub
223		if sub == nil || now.Before(sub.activatedAt) {
224			return
225		}
226		current := MonthOf(now)
227		for sub.pending != nil && !current.Before(sub.pending.EffectivePeriod) {
228			entry := termsEntry{
229				effective: sub.pending.EffectivePeriod,
230				terms:     sub.pending.Terms,
231			}
232			sub.termsHistory = append(sub.termsHistory, entry)
233			sub.planID = sub.pending.TargetPlanID
234			sub.terms = sub.pending.Terms
235			sub.pending = nil
236		}
237		if sub.cancelEnd != nil && !now.Before(*sub.cancelEnd) {
238			end := *sub.cancelEnd
239			sub.cancelEnd = nil
240			sub.pending = nil
241			sub.endedAt = &end
242			acc.history = append(acc.history, sub)
243			acc.sub = nil
244		}
245	}
246	
247	// activeSegmentAtLocked 返回覆盖时刻 at 的订阅段：activatedAt <= at < end。
248	// 优先检查当前段，再按时间倒序检查历史段。调用时持有 s.mu。
249	func activeSegmentAtLocked(acc *account, at time.Time) *subRecord {
250		if cur := acc.sub; cur != nil && !at.Before(cur.activatedAt) {
251			if cur.cancelEnd == nil || at.Before(*cur.cancelEnd) {
252				return cur
253			}
254		}
255		for i := len(acc.history) - 1; i >= 0; i-- {
256			h := acc.history[i]
257			if !at.Before(h.activatedAt) && at.Before(*h.endedAt) {
258				return h
259			}
260		}
261		return nil
262	}
263	
264	// termsForPeriod 在订阅段 sub 中返回指定账期当时适用的套餐条件快照。
265	// 条件历史按生效月份升序，取不晚于 period 的最后一条；
266	// 这样历史账单始终按该账期条件计算，不受后续换套餐影响。
267	func termsForPeriod(sub *subRecord, period Month) PlanTerms {
268		t := sub.termsHistory[0].terms
269		for _, e := range sub.termsHistory {
270			if period.Before(e.effective) {
271				break
272			}
273			t = e.terms
274		}
275		return t
276	}
277	
278	// segmentForBillingLocked 返回账期 period 应使用的订阅段：
279	// 该订阅段在该账期内确有覆盖（开通当月计入，终止当月不计入）。
280	// 完全无订阅覆盖的月份返回 nil。调用时持有 s.mu。
281	func segmentForBillingLocked(acc *account, period Month) *subRecord {
282		if cur := acc.sub; cur != nil && !period.Before(MonthOf(cur.activatedAt)) {
283			return cur
284		}
285		for i := len(acc.history) - 1; i >= 0; i-- {
286			h := acc.history[i]
287			if period.Before(MonthOf(h.activatedAt)) {
288				continue
289			}
290			if period.Before(MonthOf(*h.endedAt)) {
291				return h
292			}
293		}
294		return nil
295	}
296	
297	// SchedulePlanChange 安排账户从下一个 UTC 自然月起改用另一套餐，升级与降级规则相同。
298	//
299	// 成功时返回目标套餐在本次安排时的完整计费条件快照与生效账期（请求被接受时的
300	// 下一个 UTC 自然月），之后修改套餐定义不影响本安排。当前月仍按旧套餐收取完整
301	// 月费并提供完整额度，不按天补差，也不迁移本月已发生的用量。
302	//
303	// 每个账户至多保留一条尚未生效的安排：再次安排同一目标套餐时返回原安排，
304	// 不重新取价（Created 为 false）；安排另一目标套餐则替换原安排，生效月份仍为
305	// 本次请求被接受时的下一月。欠费停用期间也可以安排。
306	//
307	// 账户不存在、尚未开通订阅、开通时刻尚未到达、目标套餐不存在、目标套餐与当前
308	// 生效套餐相同时请求失败，原有安排保持不变。登记取消订阅会清除尚未生效的安排，
309	// 等待取消期间安排换套餐失败（ErrPlanChangeWhileCancelling）。
310	func (s *Service) SchedulePlanChange(accountID, targetPlanID string) (PlanChangeResult, error) {
311		if accountID == "" {
312			return PlanChangeResult{}, invalidf("account id is empty")
313		}
314		if targetPlanID == "" {
315			return PlanChangeResult{}, invalidf("target plan id is empty")
316		}
317		s.mu.Lock()
318		defer s.mu.Unlock()
319	
320		acc, ok := s.accounts[accountID]
321		if !ok {
322			return PlanChangeResult{}, ErrAccountNotFound
323		}
324		now := s.nowUTC()
325		// 先让已到期的安排/取消生效：例如跨月后的首次调用，此时“当前套餐”已是新套餐；
326		// 恰在换套餐生效的月初登记取消，先承认该次切换，取消从再下一月生效。
327		s.settleLocked(acc, now)
328		if acc.sub == nil {
329			return PlanChangeResult{}, ErrSubscriptionNotFound
330		}
331		if now.Before(acc.sub.activatedAt) {
332			return PlanChangeResult{}, ErrSubscriptionNotActivated
333		}
334		if acc.sub.cancelEnd != nil {
335			return PlanChangeResult{}, ErrPlanChangeWhileCancelling
336		}
337	
338		plan, ok := s.plans[targetPlanID]
339		if !ok {
340			return PlanChangeResult{}, ErrPlanNotFound
341		}
342		if targetPlanID == acc.sub.planID {
343			return PlanChangeResult{}, ErrPlanChangeSamePlan
344		}
345	
346		// 已有安排且目标相同：原样返回，不重新取价。
347		if acc.sub.pending != nil && acc.sub.pending.TargetPlanID == targetPlanID {
348			return PlanChangeResult{Created: false, Change: *acc.sub.pending}, nil
349		}
350	
351		change := PlanChange{
352			TargetPlanID:    targetPlanID,
353			Terms:           termsOf(plan),
354			EffectivePeriod: nextMonth(MonthOf(now)),
355		}
356		acc.sub.pending = &change
357		return PlanChangeResult{Created: true, Change: change}, nil
358	}
359	
360	// CancelPlanChange 在安排生效前取消它，取消后账户继续沿用当前套餐。
361	// 没有待生效安排时取消也成功；已生效的切换不会被撤回。
362	// 欠费停用期间也可以取消，取消不清除欠费、不解除停用。
363	// 账户不存在、订阅已终止（含已到终止时刻）时失败。
364	func (s *Service) CancelPlanChange(accountID string) error {
365		if accountID == "" {
366			return invalidf("account id is empty")
367		}
368		s.mu.Lock()
369		defer s.mu.Unlock()
370		acc, ok := s.accounts[accountID]
371		if !ok {
372			return ErrAccountNotFound
373		}
374		// 已到生效月份月初零点的安排视为已生效，不可撤回；已终止订阅段无当前订阅。
375		s.settleLocked(acc, s.nowUTC())
376		if acc.sub == nil {
377			return ErrSubscriptionNotFound
378		}
379		acc.sub.pending = nil
380		return nil
381	}
382	
383	// CancelSubscription 为当前有效订阅登记按月取消。
384	//
385	// 仅当订阅已生效（当前时刻不早于开通时刻）时可取消；欠费停用不妨碍取消，也不
386	// 免除债务。终止时刻为请求时刻的下一个 UTC 自然月月初零点（UTC）：当月照常
387	// 接收用量并按完整月费与额度计费，不按天退款。重复取消始终返回原终止时刻，
388	// 不把期限后移（Cancelled 为 false）。
389	//
390	// 成功时清除尚未生效的换套餐安排；若请求恰在某次换套餐生效的月初，先承认该次
391	// 切换，取消从再下一月生效。等待取消期间拒绝新的换套餐安排。
392	//
393	// 账户不存在、从未开通或当前无有效订阅、开通时刻尚未到达时请求失败。
394	func (s *Service) CancelSubscription(accountID string) (CancelSubscriptionResult, error) {
395		if accountID == "" {
396			return CancelSubscriptionResult{}, invalidf("account id is empty")
397		}
398		s.mu.Lock()
399		defer s.mu.Unlock()
400	
401		acc, ok := s.accounts[accountID]
402		if !ok {
403			return CancelSubscriptionResult{}, ErrAccountNotFound
404		}
405		now := s.nowUTC()
406		// 先补齐到期状态：恰在月初时先承认到期换套餐，终止时刻取再下一月。
407		s.settleLocked(acc, now)
408		if acc.sub == nil {
409			return CancelSubscriptionResult{}, ErrSubscriptionNotFound
410		}
411		if now.Before(acc.sub.activatedAt) {
412			return CancelSubscriptionResult{}, ErrSubscriptionNotActivated
413		}
414	
415		// 重复取消：原样返回原终止时刻，不后移期限。
416		if acc.sub.cancelEnd != nil {
417			return CancelSubscriptionResult{
418				Cancelled:    false,
419				Cancellation: SubscriptionCancellation{EndAt: *acc.sub.cancelEnd},
420			}, nil
421		}
422	
423		// 登记取消清除尚未生效的换套餐安排（撤回取消也不恢复它）。
424		acc.sub.pending = nil
425		end := nextMonth(MonthOf(now)).Start()
426		acc.sub.cancelEnd = &end
427		return CancelSubscriptionResult{
428			Cancelled:    true,
429			Cancellation: SubscriptionCancellation{EndAt: end},
430		}, nil
431	}
432	
433	// UndoCancelSubscription 在取消生效前撤回按月取消安排，撤回后订阅继续有效。
434	// 有效订阅没有取消安排时撤回也成功；撤回不恢复登记取消时被清除的换套餐安排。
435	// 终止时刻已到（订阅已终止）后撤回失败（ErrSubscriptionNotFound）；
436	// 账户不存在或从未开通时同样失败。
437	func (s *Service) UndoCancelSubscription(accountID string) error {
438		if accountID == "" {
439			return invalidf("account id is empty")
440		}
441		s.mu.Lock()
442		defer s.mu.Unlock()
443		acc, ok := s.accounts[accountID]
444		if !ok {
445			return ErrAccountNotFound
446		}
447		// 到达终止时刻后订阅已终止：撤回失败。
448		s.settleLocked(acc, s.nowUTC())
449		if acc.sub == nil {
450			return ErrSubscriptionNotFound
451		}
452		acc.sub.cancelEnd = nil
453		return nil
454	}
455	
456	// RecordEvent 上报一条用量事件。
457	//
458	// 事件按发生时刻归入 UTC 自然月账期；事件发生时刻必须属于某段实际订阅期间
459	// （开通时刻计入、终止时刻不计入），空档期间与晚于当前时刻的事件被拒绝。
460	// 订阅终止后仍可补报旧订阅期间且尚未出账的用量。
461	// 事件标识在同一账户内去重：完全相同的重报返回原结果且不重复累计——
462	// 即使发生在取消、重新开通之后也成功；相同标识但时刻或数量不同返回
463	// ErrEventConflict。
464	// 已出账月份拒绝新事件；账户因到期欠费停用时拒绝新增事件；
465	// 但此前已接收事件的完全相同重报始终成功。
466	func (s *Service) RecordEvent(e Event) (EventResult, error) {
467		if e.AccountID == "" {
468			return EventResult{}, invalidf("account id is empty")
469		}
470		if e.EventID == "" {
471			return EventResult{}, invalidf("event id is empty")
472		}
473		if e.Quantity < 0 {
474			return EventResult{}, invalidf("event %q has negative quantity %d", e.EventID, e.Quantity)
475		}
476		if e.At.IsZero() {
477			return EventResult{}, invalidf("event %q has zero timestamp", e.EventID)
478		}
479		at := e.At.UTC()
480	
481		s.mu.Lock()
482		defer s.mu.Unlock()
483	
484		acc, ok := s.accounts[e.AccountID]
485		if !ok {
486			return EventResult{}, ErrAccountNotFound
487		}
488	
489		now := s.nowUTC()
490		// 进入即补齐已到期的换套餐/取消，保证并发下各操作观察到一致的分段状态。
491		s.settleLocked(acc, now)
492	
493		// 从未开通订阅的账户没有任何订阅段。
494		if acc.sub == nil && len(acc.history) == 0 {
495			return EventResult{}, ErrSubscriptionNotFound
496		}
497	
498		// 去重优先：完全相同的重报即使发生在出账后、停用期间、取消或重新开通
499		// 之后也返回成功。
500		if prev, ok := acc.events[e.EventID]; ok {
501			if !prev.at.Equal(at) || prev.qty != e.Quantity {
502				return EventResult{}, ErrEventConflict
503			}
504			return EventResult{Accepted: false, Period: prev.period}, nil
505		}
506	
507		if at.After(now) {
508			return EventResult{}, ErrEventInFuture
509		}
510		// 事件发生时刻必须落在某段实际订阅期间：[activatedAt, end)。
511		if activeSegmentAtLocked(acc, at) == nil {
512			return EventResult{}, ErrEventBeforeSubscription
513		}
514	
515		period := MonthOf(at)
516		if _, billed := acc.bills[period]; billed {
517			return EventResult{}, ErrMonthBilled
518		}
519		if s.isSuspendedLocked(acc, now) {
520			return EventResult{}, ErrSuspended
521		}
522	
523		total, ok := addNonNeg(acc.usage[period], e.Quantity)
524		if !ok {
525			return EventResult{}, ErrOverflow
526		}
527		// 所有校验通过后才落库：失败不消耗事件标识。
528		acc.events[e.EventID] = eventRecord{at: at, qty: e.Quantity, period: period}
529		acc.usage[period] = total
530		return EventResult{Accepted: true, Period: period}, nil
531	}
532	
533	// CreateBill 为账户指定账期生成账单（账期不存在则幂等返回同一张）。
534	// 只能为某段订阅实际覆盖的、且已经结束的月份生成账单：开通当月计入、终止
535	// 当月（终止时刻所在月）不计入该段，完全无订阅的空档月份出账失败。
536	// 取消订阅不自动出账；终止后旧订阅覆盖的已结束月份仍可出账，使用各月当时
537	// 锁定的条件。重复调用得到同一账单；出账后金额与用量明细固定。
538	func (s *Service) CreateBill(accountID string, period Month) (Bill, error) {
539		if accountID == "" {
540			return Bill{}, invalidf("account id is empty")
541		}
542		if period.Month < time.January || period.Month > time.December {
543			return Bill{}, invalidf("invalid billing period %d-%d", period.Year, period.Month)
544		}
545		s.mu.Lock()
546		defer s.mu.Unlock()
547	
548		acc, ok := s.accounts[accountID]
549		if !ok {
550			return Bill{}, ErrAccountNotFound
551		}
552		if existing, ok := acc.bills[period]; ok {
553			return existing.bill, nil
554		}
555	
556		now := s.nowUTC()
557		// 补齐到期换套餐/取消（条件历史与分段），随后按账期取覆盖该月的订阅段中
558		// 当时适用的条件：即使已重新开通或先出新月份账单再补旧月份账单，历史账单
559		// 也不会被后来的订阅覆盖。
560		s.settleLocked(acc, now)
561	
562		if acc.sub == nil && len(acc.history) == 0 {
563			return Bill{}, ErrSubscriptionNotFound
564		}
565		if period.End().After(now) {
566			return Bill{}, ErrBillMonthNotEnded
567		}
568	
569		sub := segmentForBillingLocked(acc, period)
570		if sub == nil {
571			// 早于首段开通，或处于两段订阅之间的空档。
572			return Bill{}, ErrBillBeforeSubscription
573		}
574	
575		terms := termsForPeriod(sub, period)
576		bill, err := buildBill(accountID, period, terms, acc.usage[period])
577		if err != nil {
578			return Bill{}, err
579		}
580		acc.bills[period] = &billRecord{bill: bill}
581		return bill, nil
582	}
583	
584	// GetBill 返回指定账期的账单；尚未出账返回 ErrBillNotFound。
585	func (s *Service) GetBill(accountID string, period Month) (Bill, error) {
586		if accountID == "" {
587			return Bill{}, invalidf("account id is empty")
588		}
589		s.mu.Lock()
590		defer s.mu.Unlock()
591		acc, ok := s.accounts[accountID]
592		if !ok {
593			return Bill{}, ErrAccountNotFound
594		}
595		rec, ok := acc.bills[period]
596		if !ok {
597			return Bill{}, ErrBillNotFound
598		}
599		return rec.bill, nil
600	}
601	
602	// RecordPayment 为指定账单登记一笔大于零且不超过余额的本地付款，支持分次登记。
603	// 付款标识在同一账户内去重：相同账单和金额的重报仍成功，但本次不再登记
604	// （Registered 为 false），也不再次增加已付金额；返回的付款内容、账单余额与
605	// 付清状态均为该笔付款首次成功登记完成时的历史结果，不随后续付款或账单当前
606	// 状态变化（例如账单后来已结清，重报早先的部分付款仍返回当时的未清余额与
607	// 未付清）。账单查询与账户状态中的余额始终反映当前状态，不受重报影响。
608	// 相同标识但账期或金额不同返回 ErrPaymentConflict：即使原账单已结清，或改指
609	// 向的账期还没有账单，也按冲突处理而非当作新付款。失败不消耗付款标识。
610	func (s *Service) RecordPayment(accountID, paymentID string, period Month, amount int64) (PaymentResult, error) {
611		if accountID == "" {
612			return PaymentResult{}, invalidf("account id is empty")
613		}
614		if paymentID == "" {
615			return PaymentResult{}, invalidf("payment id is empty")
616		}
617		if amount <= 0 {
618			return PaymentResult{}, invalidf("payment %q amount must be positive, got %d", paymentID, amount)
619		}
620		s.mu.Lock()
621		defer s.mu.Unlock()
622	
623		acc, ok := s.accounts[accountID]
624		if !ok {
625			return PaymentResult{}, ErrAccountNotFound
626		}
627		// 去重先于账单查找：相同标识改指向其他账单（哪怕不存在）也是冲突。
628		if prev, ok := acc.payments[paymentID]; ok {
629			if prev.period != period || prev.amount != amount {
630				return PaymentResult{}, ErrPaymentConflict
631			}
632			// 完全相同的重报仍成功，但不再次登记、不改变账单：
633			// 返回这笔付款首次成功登记完成时的余额与付清状态，
634			// 不受账单后续收款、当前余额或停用/恢复状态影响。
635			return PaymentResult{
636				Registered:  false,
637				Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
638				BillBalance: prev.balance,
639				Settled:     prev.settled,
640			}, nil
641		}
642	
643		rec, ok := acc.bills[period]
644		if !ok {
645			return PaymentResult{}, ErrBillNotFound
646		}
647	
648		if amount > rec.bill.Balance {
649			return PaymentResult{}, ErrPaymentExceedsBalance
650		}
651	
652		paid, ok := addNonNeg(rec.bill.Paid, amount)
653		if !ok {
654			return PaymentResult{}, ErrOverflow
655		}
656		rec.bill.Paid = paid
657		rec.bill.Balance -= amount
658		if rec.bill.Balance == 0 {
659			rec.bill.Settled = true
660		}
661		// 保存首次登记完成时的历史结果，供完全相同重报原样返回。
662		acc.payments[paymentID] = paymentRecord{
663			period:  period,
664			amount:  amount,
665			balance: rec.bill.Balance,
666			settled: rec.bill.Settled,
667		}
668	
669		return PaymentResult{
670			Registered:  true,
671			Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
672			BillBalance: rec.bill.Balance,
673			Settled:     rec.bill.Settled,
674		}, nil
675	}
676	
677	// MonthlyUsage 返回账户某账期的累计用量；无任何用量时返回 0。
678	func (s *Service) MonthlyUsage(accountID string, period Month) (Usage, error) {
679		if accountID == "" {
680			return Usage{}, invalidf("account id is empty")
681		}
682		s.mu.Lock()
683		defer s.mu.Unlock()
684		acc, ok := s.accounts[accountID]
685		if !ok {
686			return Usage{}, ErrAccountNotFound
687		}
688		// 与其他入口保持一致：顺带让已到期的换套餐/取消生效。
689		s.settleLocked(acc, s.nowUTC())
690		return Usage{Period: period, Total: acc.usage[period]}, nil
691	}
692	
693	// Status 返回账户状态：各月累计用量、各账单余额以及当前是否因欠费停用。
694	func (s *Service) Status(accountID string) (AccountStatus, error) {
695		if accountID == "" {
696			return AccountStatus{}, invalidf("account id is empty")
697		}
698		s.mu.Lock()
699		defer s.mu.Unlock()
700		acc, ok := s.accounts[accountID]
701		if !ok {
702			return AccountStatus{}, ErrAccountNotFound
703		}
704	
705		now := s.nowUTC()
706		// 查询即让已到期安排/取消生效：月初零点或终止时刻之后无需上报用量或出账，
707		// 当前条件与订阅状态立即更新。
708		s.settleLocked(acc, now)
709	
710		// 订阅是否生效以实际开通时刻为界：提前登记、开通时刻尚未到达的订阅仍
711		// 保存在 acc.sub 中（再次开通、安排换套餐、登记取消均按已有订阅的规则
712		// 处理），但查询时刻不显示为有效订阅。到达开通时刻即生效，不按开通月份
713		// 提前生效；时刻按同一瞬间比较，使用带时区的时间结果一致。
714		active := acc.sub != nil && !now.Before(acc.sub.activatedAt)
715	
716		periodSet := make(map[Month]struct{}, len(acc.usage)+len(acc.bills))
717		for m := range acc.usage {
718			periodSet[m] = struct{}{}
719		}
720		for m := range acc.bills {
721			periodSet[m] = struct{}{}
722		}
723		periods := make([]Month, 0, len(periodSet))
724		for m := range periodSet {
725			periods = append(periods, m)
726		}
727		sortMonths(periods)
728	
729		st := AccountStatus{
730			AccountID:    accountID,
731			Subscribed:   active,
732			Suspended:    s.isSuspendedLocked(acc, now),
733			MonthlyUsage: make([]Usage, 0, len(periods)),
734			Bills:        make([]BillSummary, 0, len(acc.bills)),
735		}
736		// 仅实际生效的订阅才展示当前套餐条件、待换套餐安排与已安排终止时刻；
737		// 等待开通期间这些字段均为零值（查询不删除也不提前激活已登记订阅）。
738		if active {
739			st.CurrentTerms = acc.sub.terms
740			if acc.sub.pending != nil {
741				pending := *acc.sub.pending
742				st.PendingChange = &pending
743			}
744			if acc.sub.cancelEnd != nil {
745				end := *acc.sub.cancelEnd
746				st.ScheduledEnd = &end
747			}
748		}
749		for _, m := range periods {
750			st.MonthlyUsage = append(st.MonthlyUsage, Usage{Period: m, Total: acc.usage[m]})
751		}
752		for _, m := range periods {
753			if rec, ok := acc.bills[m]; ok {
754				b := rec.bill
755				st.Bills = append(st.Bills, BillSummary{
756					Period:   m,
757					TotalDue: b.TotalDue,
758					Paid:     b.Paid,
759					Balance:  b.Balance,
760					Settled:  b.Settled,
761					DueAt:    b.DueAt,
762				})
763			}
764		}
765		return st, nil
766	}
767	
768	// isSuspendedLocked 报告账户当前是否停用：
769	// 存在到达付款截止时刻仍有余额的账单。调用时持有 s.mu。
770	func (s *Service) isSuspendedLocked(acc *account, now time.Time) bool {
771		for _, rec := range acc.bills {
772			if !rec.bill.Settled && !now.Before(rec.bill.DueAt) {
773				return true
774			}
775		}
776		return false
777	}
778	
779	func sortMonths(ms []Month) {
780		sort.Slice(ms, func(i, j int) bool { return ms[i].Before(ms[j]) })
781	}
782	
783	// addNonNeg 返回两个非负 int64 之和；溢出时 ok=false。
784	func addNonNeg(a, b int64) (int64, bool) {
785		if a > maxInt64-b {
786			return 0, false
787		}
788		return a + b, true
789	}
790	
791	// mulNonNeg 返回两个非负 int64 之积；溢出时 ok=false。
792	func mulNonNeg(a, b int64) (int64, bool) {
793		if a == 0 || b == 0 {
794			return 0, true
795		}
796		if a > maxInt64/b {
797			return 0, false
798		}
799		return a * b, true
800	}
801	
802	// buildBill 依据套餐快照和账期总用量计算账单，所有金额运算做溢出检查。
803	func buildBill(accountID string, period Month, t PlanTerms, totalUsage int64) (Bill, error) {
804		overageUnits := int64(0)
805		if totalUsage > t.IncludedUnits {
806			overageUnits = totalUsage - t.IncludedUnits
807		}
808		overageFee, ok := mulNonNeg(overageUnits, t.OveragePrice)
809		if !ok {
810			return Bill{}, ErrOverflow
811		}
812		subtotal, ok := addNonNeg(t.MonthlyFee, overageFee)
813		if !ok {
814			return Bill{}, ErrOverflow
815		}
816		tax, ok := rateAmount(subtotal, t.TaxRateBasisPoints)
817		if !ok {
818			return Bill{}, ErrOverflow
819		}
820		totalDue, ok := addNonNeg(subtotal, tax)
821		if !ok {
822			return Bill{}, ErrOverflow
823		}
824		b := Bill{
825			AccountID:     accountID,
826			Period:        period,
827			Terms:         t,
828			TotalUsage:    totalUsage,
829			IncludedUnits: t.IncludedUnits,
830			OverageUnits:  overageUnits,
831			MonthlyFee:    t.MonthlyFee,
832			OverageFee:    overageFee,
833			Tax:           tax,
834			TotalDue:      totalDue,
835			Paid:          0,
836			Balance:       totalDue,
837			Settled:       totalDue == 0,
838			DueAt:         period.End().AddDate(0, 0, 7),
839		}
840		return b, nil
841	}
842	
843	// rateAmount 计算 amount*rate/10000 并四舍五入到分（非负数，半数向上）。
844	// 拆分商和余数计算以避免乘积溢出 int64。
845	func rateAmount(amount, rate int64) (int64, bool) {
846		const den = 10000
847		q, r := amount/den, amount%den
848		qr, ok := mulNonNeg(q, rate)
849		if !ok {
850			return 0, false
851		}
852		rr, ok := mulNonNeg(r, rate)
853		if !ok {
854			return 0, false
855		}
856		// 四舍五入：(rr + den/2) / den，rr < den*10001 < 1e8，加 den/2 不溢出。
857		add, ok := addNonNeg(qr, (rr+den/2)/den)
858		if !ok {
859			return 0, false
860		}
861		return add, true
862	}
863

